insert into reglas (clave, jurisdiccion, dimension, titulo, texto_resumen,
                    fuente_cita, fuente_url, source_version, vigente_desde, vigente_hasta) values
  ('MX-LGSM-228BIS-ESCISION', 'MX', 'regulatorio', 'Escision de sociedades: resolucion de asamblea, publicidad y oposicion (45 dias)', 'Hay escision cuando una sociedad (escindente) divide la totalidad o parte de su activo, pasivo y capital en dos o mas partes aportadas en bloque a sociedades de nueva creacion (escindidas), extinguiendose o no (Art. 228 Bis). Solo puede acordarse por resolucion de la asamblea con los requisitos de quorum de reforma estatutaria; la resolucion (con la informacion prescrita) se protocoliza, se inscribe en el RPC y un extracto se publica en el sistema electronico de la Secretaria de Economia, quedando el texto completo a disposicion de socios y acreedores durante 45 DIAS NATURALES desde la inscripcion y publicacion; en ese plazo socios o acreedores que representen los porcentajes de ley pueden oponerse judicialmente.',
   'LGSM, Art. 228 Bis (adicionado DOF 11-06-1992; publicidad electronica reformada DOF 13-06-2014; texto vigente, ultima reforma DOF 20-10-2023)', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LGSM.pdf', 'seed v4 2026-07-30 — LISR/CFF (MX), ET (CO), NIF CINIF, CCF/CCom (MX); verificar contra fuente oficial (DOF/DIAN) antes de produccion; regulatorio MX 2026-07: Ley de Aviacion Civil (reforma consolidada DOF 14-11-2025) + NOM-107-SCT3-2019, Ley de Instituciones de Seguros y de Fianzas (texto vigente DOF 14-11-2025, Art. 91/93/94 sin evidencia de reforma posterior a su publicacion original DOF 04-04-2013) — verificado contra texto primario, no contra blogs de terceros. Fase 8b (2026-07-10): categoria AGENTES_SEGUROS + exclusiones en el clasificador para que no colisione con DRONES_DELIVERY (incidente real en #dep-legal). datos-personales MX 2026-07-30: LFPDPPP NUEVA LEY (publicada DOF 20-03-2025, vigente 21-03-2025, texto vigente con ultima reforma DOF 14-11-2025; la ley de 2010 quedo ABROGADA por el Transitorio Segundo del Decreto; autoridad de proteccion de datos: Secretaria Anticorrupcion y Buen Gobierno — INAI extinto, Art. 3 fraccion XV). Arts. 3-X, 5, 6, 9-II, 14, 15, 16, 17, 20, 35 y 36 verificados contra el PDF oficial de Diputados (LeyesBiblio), no contra blogs. La regla MX-LFPDPPP-21-CONFIDENCIALIDAD (ley 2010) se retira via _bajas y la sustituye MX-LFPDPPP2025-20-CONFIDENCIALIDAD. corporativo-mercantil MX 2026-08-06 (Fase A): LGSM texto vigente (ultima reforma DOF 20-10-2023, cantidades actualizadas por Acuerdo DOF 26-12-2025 — tope SAS $7,678,849.94 leido del PDF oficial), CFF (ultima reforma DOF 09-04-2026, Arts. 32-B Ter/84-M cotejados) y LFCE (ultima reforma DOF 14-11-2025; umbrales del Art. 86 REFORMADOS DOF 16-07-2025 a 16M/30%+16M/7.4M+40M UMA, leidos del PDF oficial — los umbrales pre-reforma 18M/48M/8.4M quedan obsoletos). Arts. 2, 5, 6, 10, 19, 20, 128, 129, 178, 180-182, 186, 222-225, 228 Bis y 260-263 LGSM verificados contra el PDF de Diputados