  select r.id, 'TESTAMENTOS_SUCESIONES', 'GENERAL', 'permitido',
         null, null,
         '["Otorgamiento individual: nunca dos personas en el mismo acto, ni en provecho reciproco (Art. 1296)", "Elegir la clase de testamento adecuada (Art. 1500); el publico abierto exige notario y sus formalidades (Arts. 1511 y ss.)", "Capacidad del testador conforme al propio Codigo"]'::jsonb, '["La materia civil (sucesiones e inmuebles) es competencia LOCAL: el CCF es la referencia federal; cotejar el codigo civil y la ley registral del estado donde este el bien o se abra la sucesion", "El fideicomiso TESTAMENTARIO combina esta materia con la LGTOC (ver FIDEICOMISO_CONSTITUCION y sus prohibiciones del Art. 394)"]'::jsonb, '{"verificar": false}'::jsonb
  from reglas r where r.clave = 'MX-CCF-1295-1511-TESTAMENTO'
  on conflict (regla_id, categoria, regimen) do update set
