insert into reglas (clave, jurisdiccion, dimension, titulo, texto_resumen,
                    fuente_cita, fuente_url, source_version, vigente_desde, vigente_hasta) values
  ('MX-CCF-2317-2320-FORMA-COMPRAVENTA', 'MX', 'regulatorio', 'Compraventa de inmuebles: documento privado solo bajo el umbral; arriba, escritura publica', 'Las enajenaciones de inmuebles cuyo valor de avaluo NO exceda el equivalente a 365 veces el salario minimo general diario vigente en el Distrito Federal al momento de la operacion (y la constitucion/transmision de derechos reales hasta esa cantidad) pueden otorgarse en documento privado firmado ante dos testigos, con ratificacion de firmas (Art. 2317). Si el valor de avaluo EXCEDE ese umbral, la venta debe hacerse en ESCRITURA PUBLICA (Art. 2320). Tras la desindexacion del salario minimo (reforma constitucional 2016), el calculo del umbral debe cotejarse con la UMA y el criterio local aplicable.',
