insert into impactos (regla_id, categoria, regimen, veredicto_base,
                      tope_monto, tope_pct, requisitos, banderas, parametros)
  select r.id, 'CABILDEO_CONGRESO', 'GENERAL', 'permitido',
         null, null,
         '["Inscribirse en el registro publico de cabilderos de la Mesa Directiva al inicio de la legislatura si se cabildeara mas de una vez (Art. 264-1)", "Respetar los cupos: hasta 20 acreditados por comision y 2 por persona moral (Art. 264-4) — planear que personas del despacho/holding se acreditan", "Identificar al representado en la solicitud (persona moral: relacion de acreditados por el representante legal, Art. 267)", "Asumir la publicidad: los documentos de cabildeo se archivan por comision y son de consulta publica (Art. 266)"]'::jsonb, '["Servidores publicos en funciones, sus conyuges y parientes hasta 4o grado NO pueden cabildear (Art. 264-3) — verificar conflictos en el equipo", "Este regimen aplica a la Camara de Diputados; el Senado tiene el suyo (Arts. 298-299 de su Reglamento) y el cabildeo ante el Ejecutivo NO tiene registro federal equivalente — hueco normativo a declarar"]'::jsonb, '{"max_acreditados_por_comision": 20, "max_por_persona_moral": 2, "verificar": true}'::jsonb
  from reglas r where r.clave = 'MX-REGDIP-263-268-CABILDEO'
  on conflict (regla_id, categoria, regimen) do update set
    veredicto_base = excluded.veredicto_base, tope_monto = excluded.tope_monto,
    tope_pct = excluded.tope_pct, requisitos = excluded.requisitos,
    banderas = excluded.banderas, parametros = excluded.parametros;

insert into reglas (clave, jurisdiccion, dimension, titulo, texto_resumen,
                    fuente_cita, fuente_url, source_version, vigente_desde, vigente_hasta) values
  ('MX-REGSEN-298-299-CABILDEO', 'MX', 'regulatorio', 'Cabildeo en el Senado: promocion de intereses legitimos con informes a la Mesa y prohibicion de dadivas', 'En el Senado, cabildeo es la actividad de personas dedicadas a promover intereses LEGITIMOS de particulares ante organos directivos, comisiones o senadores, con el proposito de influir en sus decisiones (Art. 298-1). Las comisiones y senadores INFORMAN por escrito a la Mesa de las actividades realizadas ante ellos por cabilderos (298-2). Los senadores y el personal de apoyo no pueden aceptar dadivas o pagos en efectivo relacionados con esas gestiones (Art. 299).',
   'Reglamento del Senado de la Republica, Arts. 298 y 299 (texto vigente, ultima reforma DOF 06-12-2024)', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/Reg_Senado.pdf', 'seed v4 2026-07-30 — LISR/CFF (MX), ET (CO), NIF CINIF, CCF/CCom (MX); verificar contra fuente oficial (DOF/DIAN) antes de produccion; regulatorio MX 2026-07: Ley de Aviacion Civil (reforma consolidada DOF 14-11-2025) + NOM-107-SCT3-2019, Ley de Instituciones de Seguros y de Fianzas (texto vigente DOF 14-11-2025, Art. 91/93/94 sin evidencia de reforma posterior a su publicacion original DOF 04-04-2013) — verificado contra texto primario, no contra blogs de terceros. Fase 8b (2026-07-10): categoria AGENTES_SEGUROS + exclusiones en el clasificador para que no colisione con DRONES_DELIVERY (incidente real en #dep-legal). datos-personales MX 2026-07-30: LFPDPPP NUEVA LEY (publicada DOF 20-03-2025, vigente 21-03-2025, texto vigente con ultima reforma DOF 14-11-2025; la ley de 2010 quedo ABROGADA por el Transitorio Segundo del Decreto; autoridad de proteccion de datos: Secretaria Anticorrupcion y Buen Gobierno — INAI extinto, Art. 3 fraccion XV). Arts. 3-X, 5, 6, 9-II, 14, 15, 16, 17, 20, 35 y 36 verificados contra el PDF oficial de Diputados (LeyesBiblio), no contra blogs. La regla MX-LFPDPPP-21-CONFIDENCIALIDAD (ley 2010) se retira via _bajas y la sustituye MX-LFPDPPP2025-20-CONFIDENCIALIDAD. corporativo-mercantil MX 2026-08-06 (Fase A): LGSM texto vigente (ultima reforma DOF 20-10-2023, cantidades actualizadas por Acuerdo DOF 26-12-2025 — tope SAS $7,678,849.94 leido del PDF oficial), CFF (ultima reforma DOF 09-04-2026, Arts. 32-B Ter/84-M cotejados) y LFCE (ultima reforma DOF 14-11-2025; umbrales del Art. 86 REFORMADOS DOF 16-07-2025 a 16M/30%+16M/7.4M+40M UMA, leidos del PDF oficial — los umbrales pre-reforma 18M/48M/8.4M quedan obsoletos). Arts. 2, 5, 6, 10, 19, 20, 128, 129, 178, 180-182, 186, 222-225, 228 Bis y 260-263 LGSM verificados contra el PDF de Diputados (LeyesBiblio), no contra blogs ni