insert into impactos (regla_id, categoria, regimen, veredicto_base,
                      tope_monto, tope_pct, requisitos, banderas, parametros)
  select r.id, 'APORTACIONES_POLITICAS', 'GENERAL', 'no_permitido',
         null, null,
         '["Politica interna del grupo: ninguna sociedad aporta a partidos/campanas, ni en dinero ni en especie, ni via terceros (la interposita persona esta expresamente cubierta por la prohibicion)", "Cuidado con aportaciones EN ESPECIE encubiertas: prestar personal, oficinas, vehiculos o servicios del despacho a una campana cae en el supuesto"]'::jsonb, '["Las personas FISICAS mexicanas si pueden aportar con limites y reglas de fiscalizacion (LGPP Arts. 53-56): el dictamen de esa via requiere sus topes vigentes — cotejar", "Algunos incisos del Art. 54 fueron objeto de sentencia de la SCJN (accion de inconstitucionalidad, efectos publicados DOF 24-11-2023) que restauro texto previo: cotejar el inciso exacto antes de citar en un caso"]'::jsonb, '{"verificar": false}'::jsonb
  from reglas r where r.clave = 'MX-LGPP-54-APORTACIONES-PROHIBIDAS'
  on conflict (regla_id, categoria, regimen) do update set
    veredicto_base = excluded.veredicto_base, tope_monto = excluded.tope_monto,
