insert into impactos (regla_id, categoria, regimen, veredicto_base,
                      tope_monto, tope_pct, requisitos, banderas, parametros)
  select r.id, 'ASESORIA_INVERSIONES', 'GENERAL', 'permitido',
         null, null,
         '["Test de frontera ANTES de vender el servicio: ¿recomendaciones de inversion individualizadas o manejo de portafolios por cuenta de terceros, de forma habitual y profesional? Si NO (finanzas corporativas, valuacion, planeacion), no es actividad reservada", "Si SI: registrarse ante la CNBV como asesor en inversiones ANTES de operar (Art. 225)", "El vehiculo debe ser dedicado: SC/SA/S de RL con objeto social especifico y establecimientos exclusivos — no se agrega esta actividad a una operativa multi-servicios del holding (Art. 225, fr. I-III)", "Personas fisicas del equipo que asesoren: certificacion ante organismo autorregulatorio reconocido por la CNBV"]'::jsonb, '["Frontera VECINA mas dura: recibir dinero de clientes para gestionarlo = captacion (LIC), territorio de delito financiero sin autorizacion — dictamen aparte URGENTE si el servicio toca recursos de terceros", "Intermediacion de valores (casa de bolsa) y fondos de inversion son autorizaciones DISTINTAS y mas pesadas que el registro de asesor", "Fondeo colectivo y activos virtuales van por la Ley Fintech — regimen propio, no cubierto por esta regla"]'::jsonb, '{"verificar": false}'::jsonb
  from reglas r where r.clave = 'MX-LMV-225-ASESOR-INVERSIONES'
  on conflict (regla_id, categoria, regimen) do update set
    veredicto_base = excluded.veredicto_base, tope_monto = excluded.tope_monto,
    tope_pct = excluded.tope_pct, requisitos = excluded.requisitos,
    banderas = excluded.banderas, parametros = excluded.parametros;

insert into reglas (clave, jurisdiccion, dimension, titulo, texto_resumen,
                    fuente_cita, fuente_url, source_version, vigente_desde, vigente_hasta) values
  ('MX-LFPPI-170-178-MARCA-REGISTRO', 'MX', 'regulatorio', 'Marcas: usarlas es libre, pero el derecho EXCLUSIVO solo se obtiene con el registro ante el IMPI', 'Cualquier persona fisica o moral puede usar marcas en la industria, el comercio o los servicios que preste; el derecho a su uso EXCLUSIVO se obtiene unicamente mediante el registro en el Instituto (Art. 170). El registro de marca tiene una vigencia de diez anos contados a partir de la fecha de su OTORGAMIENTO y se renueva por periodos de la misma duracion (Art. 178); el aviso comercial sigue la misma regla (Art. 204). La renovacion se solicita dentro de los seis meses ANTERIORES al vencimiento, y el Instituto da tramite a las presentadas dentro de los seis meses POSTERIORES (Art. 237). Vencido ese plazo sin solicitud, el registro caduca de pleno derecho, sin que se requiera declaracion del Instituto (Art. 238).',
   'LFPPI, Arts. 170, 174, 178, 204, 236, 237 y 238 (nueva ley DOF 01-07-2020, en vigor 05-11-2020 conforme a su Transitorio PRIMERO (90 dias habiles); texto vigente, ultima reforma DOF 03-04-2026)', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LFPPI.pdf', 'seed v4 2026-07-30 — LISR/CFF (MX), ET (CO), NIF CINIF, CCF/CCom (MX); verificar contra fuente oficial (DOF/DIAN) antes de produccion; regulatorio MX 2026-07: Ley de Aviacion Civil (reforma consolidada DOF 14-11-2025) + NOM-107-SCT3-2019, Ley de Instituciones de Seguros y de Fianzas (texto vigente DOF 14-11-2025, Art. 91/93/94 sin evidencia de reforma posterior a su publicacion original DOF 04-04-2013) — verificado contra texto primario, no contra blogs de terceros. Fase 8b (2026-07-10): categoria AGENTES_SEGUROS + exclusiones en el clasificador para que no colisione con DRONES_DELIVERY (incidente real en #dep-legal). datos-personales MX 2026-07-30: LFPDPPP NUEVA LEY (publicada DOF 20-03-2025, vigente 21-03-2025, texto vigente con ultima reforma DOF 14-11-2025; la ley de 2010 quedo ABROGADA por el Transitorio Segundo del Decreto; autoridad de proteccion de datos: Secretaria Anticorrupcion y Buen Gobierno — INAI extinto, Art. 3 fraccion XV). Arts. 3-X, 5, 6, 9-II, 14, 15, 16, 17, 20, 35 y 36 verificados contra el PDF oficial de Diputados (LeyesBiblio), no contra blogs. La regla MX-LFPDPPP-21-CONFIDENCIALIDAD (ley 2010) se retira via _bajas y la sustituye MX-LFPDPPP2025-20-CONFIDENCIALIDAD. corporativo-mercantil MX 2026-08-06 (Fase A): LGSM texto vigente (ultima reforma DOF 20-10-2023, cantidades actualizadas por Acuerdo DOF 26-12-2025 — tope SAS $7,678,849.94 leido del PDF oficial), CFF (ultima reforma DOF 09-04-2026, Arts. 32-B Ter/84-M cotejados) y LFCE (ultima reforma DOF 14-11-2025; umbrales del Art. 86 REFORMADOS DOF 16-07-2025 a 16M/30%+16M/7.4M+40M UMA, leidos del PDF oficial — los umbrales pre-reforma 18M/48M/8.4M quedan obsoletos). Arts. 2, 5, 6, 10, 19, 20, 128, 129, 178, 180-182, 186, 222-225, 228 Bis y 260-263 LGSM verificados contra el PDF de Diputados (LeyesBiblio), no contra blogs ni memoria. fiduciario/sucesorio/inmobiliario MX 2026-08-07 (Fase B): LGTOC texto vigente (ultima reforma DOF 26-03-2024, Arts. 381-394 cotejados — prohibiciones del 394 incl. limite de 50 anos con excepcion de museos), CCF (ultima reforma DOF 14-11-2025, Arts. 1295-1296/1500-1501/1511, 1599/1602, 2317/2320 con umbral de 365 salarios minimos pendiente de conversion UMA, 3007-3009) y LIE (ultima reforma DOF 27-05-2024, Arts. 2-VI y 10-14: zona restringida 100/50 km, fideicomiso 50 anos prorrogable, permiso SRE). Todo leido de los PDF de Diputados (LeyesBiblio), no de memoria. Bandera transversal: la materia civil es LOCAL — el CCF es referencia federal, cotejar el codigo del estado. ambiental MX 2026-08-07 (Fase C): LGEEPA texto vigente (ultima reforma DOF 19-01-2026, Arts. 28/30 EIA con las 10 fracciones leidas del PDF, 38-38 Bis auditoria voluntaria, 111 Bis fuentes fijas federales con su lista de industrias), LGPGIR (ultima reforma DOF 19-01-2026, categorias de generador del Art. 5 fr. XII/XIX/XX: micro <=400 kg/ano, pequeno 400 kg-<10 t, gran >=10 t; Arts. 42/44/46) y LFRA (ultima reforma DOF 14-11-2025, Arts. 1o/10: reparacion prioritaria, compensacion subsidiaria, responsabilidad por dano indirecto). Todo leido de los PDF de Diputados (LeyesBiblio). El veredicto de RESPONSABILIDAD_AMBIENTAL es no_permitido (ocasionar dano ambiental genera responsabilidad objetiva), unico en su categoria — sin conflicto de veredictos. cabildeo/politico MX 2026-08-07 (Fase D): Reglamento de la Camara de Diputados (ultima reforma DOF 07-05-2025, Arts. 263-268: registro por legislatura, cupos 20 por comision / 2 por persona moral, veto a servidores publicos y parientes 4o grado, archivo publico), Reglamento del Senado (ultima reforma DOF 06-12-2024, Arts. 298-299: informes a la Mesa, sin dadivas), LGPP (ultima reforma DOF 02-03-2023, Art. 54-1-f/g: personas morales y residentes en el extranjero NO 